{% if Detail.entryStartDate and Detail.entryEndDate %}
    <div class="p-hareruya-event-detail__info-row">
        <dt class="p-hareruya-event-detail__info-label">{{ 'front.event.detail.info.entry_period'|trans }}</dt>
        <dd class="p-hareruya-event-detail__info-value">
            <time datetime="{{ Detail.entryStartDate|date('Y-m-d\\TH:i') }}">{{ Detail.entryStartDate|date('Y/n/j H:i') }}</time>
            &nbsp;～&nbsp;
            <time datetime="{{ Detail.entryEndDate|date('Y-m-d\\TH:i') }}">{{ Detail.entryEndDate|date('Y/n/j H:i') }}</time>
        </dd>
    </div>
{% endif %}

private function isWithinEntryWindow(DtbEventDetail $Detail, \DateTimeImmutable $now): bool
{
    $start = $Detail->getOnlineEntryStartDate();
    $end = $Detail->getOnlineEntryEndDate();
    if ($start === null || $end === null) {
        return false;
    }

    $startImmutable = \DateTimeImmutable::createFromInterface($start);
    $endImmutable = \DateTimeImmutable::createFromInterface($end);

    return $now >= $startImmutable && $now <= $endImmutable;
}

#[ORM\Column(name: 'entry_start_date', type: Types::DATETIMETZ_MUTABLE, nullable: true, options: ['comment' => '申込開始日時'])]
private ?\DateTime $entryStartDate = null;

#[ORM\Column(name: 'entry_end_date', type: Types::DATETIMETZ_MUTABLE, nullable: true, options: ['comment' => '申込終了日時'])]
private ?\DateTime $entryEndDate = null;

#[ORM\Column(name: 'online_entry_start_date', type: Types::DATETIMETZ_MUTABLE, nullable: true, options: ['comment' => 'オンライン申込開始日時'])]
private ?\DateTime $onlineEntryStartDate = null;

#[ORM\Column(name: 'online_entry_end_date', type: Types::DATETIMETZ_MUTABLE, nullable: true, options: ['comment' => 'オンライン申込終了日時'])]
private ?\DateTime $onlineEntryEndDate = null;
